const rows=range(0,98,2);
section('Hull',[
rows.map(z=>{const h=H(z);return box({at:[-h,0,z],size:[2*h,3,2],colour:DG,interior:'solid'});}),
rows.map(z=>{const h=H(z)-1;return box({at:[-h,3,z],size:[2*h,3,2],colour:'hull',texture:'grille'});}),
rows.filter(z=>z>=6).map(z=>{const h=H(z)-3;return box({at:[-h,6,z],size:[2*h,3,2],colour:'hull',texture:'masonry'});}),
rows.filter(z=>z>=6).map(z=>{const h=H(z)-3;return floor({at:[-h,9,z],size:[2*h,2],layers:1,colour:'plate',top:'tile'});})
]);
section('Superstructure',[
rows.filter(z=>z>=20).map(z=>{const s=HS(z);return [box({at:[-s,10,z],size:[2*s,3,2],colour:'hull',texture:'grille'}),box({at:[-s,13,z],size:[2*s,3,2],colour:'plate',interior:'solid',top:'tile'})];}),
rows.filter(z=>z>=64).map(z=>{const c=HC(z);return [box({at:[-c,16,z],size:[2*c,3,2],colour:'hull',texture:'masonry'}),box({at:[-c,19,z],size:[2*c,3,2],colour:'plate',interior:'solid',top:'tile'})];})
]);
section('Tower',[
box({at:[-6,22,80],size:[12,9,12],colour:'plate',top:'tile',quoins:DG}),
box({at:[-4,31,82],size:[8,6,8],colour:LG,top:'tile'}),
box({at:[-2,37,84],size:[4,6,4],colour:DG,interior:'solid'}),
box({at:[-10,43,83],size:[20,12,6],colour:LG,top:'tile'}),
[-9,-5,-1,3,7].map(x=>window({at:[x,46,83],facing:'front',size:'1x2x2',frame:DG})),
[-9,-5,-1,3,7].map(x=>window({at:[x,46,88],facing:'back',size:'1x2x2',frame:DG})),
dome({at:[-10,55,83],diameter:6,colour:LG}),
dome({at:[4,55,83],diameter:6,colour:LG}),
place({part:'3957a',at:[-1,55,85],colour:DG}),
place({part:'3957a',at:[0,55,86],colour:DG})
]);
const eng=(x,y,W,widths)=>[widths.map((w,i)=>box({at:[x+(W-w)/2,y+3*i,103],size:[w,3,3],colour:DG,interior:'solid'})),widths.map((w,i)=>box({at:[x+(W-w)/2+1,y+3*i,106],size:[w-2,3,1],colour:'trans light blue',interior:'solid'}))];
section('Stern and engines',[
