eng(-5,2,10,[4,8,10,10,8,4]),eng(-16,2,8,[4,6,8,8,6,4]),eng(8,2,8,[4,6,8,8,6,4]),eng(-25,5,6,[4,6,6,4]),eng(19,5,6,[4,6,6,4]),
range(-27,27,3).map(x=>place({part:'4070',at:[x,22,102],colour:DG,turn:180}))
