else if(r<0.96){gOps.push(place({part:'3005',at:[x,y,z],colour:DG}));gOps.push(place({part:'54200',at:[x,y+3,z],colour:LG}));}
else gOps.push(place({part:'4589',at:[x,y,z],colour:LG}));};
for(let z=8;z<98;z++){const z0=z-(z%2);const hl=H(z0)-3;if(z0>=20){const hs=HS(z0);for(let x=-hl;x<=-hs-1;x++)g(x,10,z,0.3);for(let x=hs;x<=hl-1;x++)g(x,10,z,0.3);}else{for(let x=-hl;x<=hl-1;x++)g(x,10,z,0.3);}}
for(let z=20;z<64;z++){const s=HS(z-(z%2));for(let x=-s;x<=s-1;x++)g(x,16,z,0.3);}
for(let z=64;z<98;z++){const z0=z-(z%2);const s=HS(z0),c=HC(z0);for(let x=-s;x<=-c-1;x++)g(x,16,z,0.3);for(let x=c;x<=s-1;x++)g(x,16,z,0.3);for(let x=-c;x<=c-1;x++){if(z>=80&&z<=91&&x>=-6&&x<=5)continue;g(x,22,z,0.35);}}
section('Turrets and greebles',gOps);
